(function(root){
'use strict';
const regions={orchard:{name:'Bramble Orchard',npc:'Tessa',role:'Botanist',icon:'seed',needs:{herbs:12,berries:18},line:'Help me bring the old nursery back to life.'},highlands:{name:'Copper Highlands',npc:'Rowan',role:'Surveyor',icon:'tool',needs:{ore:10,wood:18},line:'The old lift needs a steady hand and good copper.'},marsh:{name:'Fernwater Marsh',npc:'Iris',role:'Wetland keeper',icon:'fish',needs:{herbs:16,fish:9},line:'Every boardwalk we repair brings the marsh a little closer.'},coast:{name:'Tideglass Coast',npc:'Kai',role:'Harbour keeper',icon:'map',needs:{shells:14,fish:12},line:'The tide always brings something new.'},observatory:{name:'Starlight Plateau',npc:'Sage',role:'Astronomer',icon:'crystals',needs:{crystals:16,ore:14},line:'There is a story written in these old lenses.'}};
const projects={nursery:{name:'Restore the nursery',region:'orchard',icon:'seed',cost:{wood:120,berries:80,herbs:20,marks:2},reward:'Harvests yield +1 crop. Opens the marsh trail.'},lift:{name:'Repair the copper lift',region:'highlands',icon:'tool',cost:{wood:180,ore:30,coins:150,marks:4},reward:'Ore gathering yields +1. Opens the plateau.'},harbour:{name:'Rebuild the harbour',region:'coast',icon:'home',cost:{wood:220,fish:45,herbs:35,marks:6},reward:'Fishing yields +1. Opens the coast road.'},boardwalk:{name:'Restore the boardwalks',region:'marsh',icon:'map',cost:{wood:160,herbs:45,ore:20,marks:5},reward:'Herb gathering yields +1.'},observatory:{name:'Rekindle the observatory',region:'observatory',icon:'crystals',cost:{crystals:100,ore:50,shells:40,marks:8},reward:'Crystal gathering yields +1; expedition rewards improve.'}};
const routes={300:{name:'Trail patrol',minutes:5,marks:1,items:{herbs:3}},1200:{name:'Valley survey',minutes:20,marks:3,items:{ore:8,herbs:5}},3600:{name:'Frontier expedition',minutes:60,marks:7,items:{shells:15,ore:15}}};
function unlocked(s,id){return id==='marsh'?!!s.frontier.projects.nursery:id==='coast'?!!s.frontier.projects.harbour:id==='observatory'?!!s.frontier.projects.lift:true;}
function amount(s,k){return k==='marks'?s.frontier.marks:s[k]||0;}
function costs(s,c){return Object.entries(c).every(([k,n])=>amount(s,k)>=n);}
function spend(s,c){for(const[k,n]of Object.entries(c)){if(k==='marks')s.frontier.marks-=n;else s[k]-=n;}}
function build(s,id){const p=projects[id];if(!p||s.frontier.projects[id]||!costs(s,p.cost))return false;if(id==='boardwalk'&&!unlocked(s,'marsh')||id==='observatory'&&!unlocked(s,'observatory'))return false;spend(s,p.cost);s.frontier.projects[id]=true;s.xp+=80;return true;}
// Requests rotate through four kinds so reputation isn't always the same gathering errand.
const kinds=['gather','farm','discover','craft'];
function requestKind(s,id){return kinds[(s.frontier.completed+Object.keys(regions).indexOf(id))%kinds.length];}
function accept(s,id){if(!regions[id]||!unlocked(s,id)||s.frontier.orders[id])return false;s.frontier.orders[id]={tier:s.frontier.completed,kind:requestKind(s,id),start:{...s.frontier.gathered,harvested:s.life.harvested,crafted:s.life.crafted,visits:s.life.visits.length}};return true;}
function needs(order,id){const kind=order.kind||'gather',scale=1+Math.min(2,Math.floor(order.tier/5)*.2);if(kind==='farm')return {harvested:Math.ceil(3*scale)};if(kind==='discover')return {visits:1};if(kind==='craft')return {crafted:Math.ceil(2*scale)};return Object.fromEntries(Object.entries(regions[id].needs).map(([k,n])=>[k,Math.ceil(n*scale)]));}
function progress(s,id){const o=s.frontier.orders[id];if(!o)return [];const trackers={harvested:()=>s.life.harvested-o.start.harvested,crafted:()=>s.life.crafted-o.start.crafted,visits:()=>s.life.visits.length-o.start.visits};return Object.entries(needs(o,id)).map(([k,n])=>({item:k,need:n,have:Math.max(0,Math.min(n,trackers[k]?trackers[k]():(s.frontier.gathered[k]||0)-(o.start[k]||0)))}));}
function deliver(s,id){const o=s.frontier.orders[id];if(!o||!progress(s,id).every(p=>p.have>=p.need))return false;const kind=o.kind||'gather';if(kind==='gather'){if(!costs(s,needs(o,id)))return false;spend(s,needs(o,id));}s.frontier.marks+=3;s.frontier.completed++;s.coins+=50+Math.min(200,o.tier*5);s.xp+=25;delete s.frontier.orders[id];return true;}
function dispatch(s,name,duration,now=Date.now()){if(!s.team.includes(name)||name===s.life.active||s.frontier.trips[name]||!routes[duration]||(duration===1200&&s.frontier.completed<3)||(duration===3600&&s.frontier.completed<6)||s.berries<10)return false;s.berries-=10;s.frontier.trips[name]={start:now,duration};return true;}
function claimTrip(s,name,now=Date.now()){const t=s.frontier.trips[name];if(!t||now<t.start+t.duration*1000)return false;const r=routes[t.duration];s.frontier.marks+=r.marks+(s.frontier.projects.observatory?1:0);for(const[k,n]of Object.entries(r.items))s[k]+=n;s.life.bond[name]=Math.min(900,(s.life.bond[name]||0)+25);delete s.frontier.trips[name];return true;}
function idle(s,now,rates){const start=s.last,dt=Math.max(0,Math.min(now-start,8*3600000)),end=start+dt;for(const n of s.team){const job=s.jobs[n],trip=s.frontier?.trips[n];if(!rates[job])continue;const overlap=trip?Math.max(0,Math.min(end,trip.start+trip.duration*1000)-Math.max(start,trip.start)):0;s.bank[job]=(s.bank[job]||0)+(dt-overlap)/1000/rates[job]*s.upgrade;}s.last=now;return dt;}
const api={regions,projects,routes,kinds,unlocked,amount,costs,build,accept,needs,progress,deliver,dispatch,claimTrip,idle};if(typeof module!=='undefined')module.exports=api;else root.FrontierCore=api;
})(globalThis);
